/* @component: custom-select */
(function () {
  function initSelects() {
    document.querySelectorAll('.custom-select').forEach(function (select) {
      if (select.dataset.initialized === 'true') return;
      select.dataset.initialized = 'true';
      const btn = select.querySelector('.dropdown-button');
      const span = select.querySelector('.dropdown-button span');
      const hidden = select.querySelector('input[type="hidden"]');
      const items = select.querySelectorAll('.dropdown-list__item');
      if (!btn) return;
      btn.addEventListener('click', function (e) {
        e.stopPropagation();
        const wasActive = select.classList.contains('_is-active');
        document.querySelectorAll('.custom-select._is-active').forEach(function (s) {
          s.classList.remove('_is-active');
        });
        if (!wasActive) select.classList.add('_is-active');
      });
      items.forEach(function (item) {
        item.addEventListener('click', function (e) {
          e.stopPropagation();
          const val = item.getAttribute('data-value') || item.textContent.trim();
          if (hidden) hidden.value = val;
          if (span) span.textContent = val;
          select.classList.remove('_is-active');
        });
      });
    });
    document.addEventListener('click', function () {
      document.querySelectorAll('.custom-select._is-active').forEach(function (s) {
        s.classList.remove('_is-active');
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSelects);
  } else {
    initSelects();
  }
  setTimeout(initSelects, 300);
})();
/* @end: custom-select */
